        Ok(len) => len,
        Err(err) => {
            write.abandon().await;
            return Err(err);
        }
    };
    write.finalize().await.map_err(TarballStreamError::Io)?;
    Ok(len)
}

pub async fn download_verified_to_temp(
    response: reqwest::Response,
    mut write: TarballWrite,
    integrity: &Integrity,
    max_bytes: u64,
